      "假设一个链表比另 一个链表长 k 个结点，我们先在长链表上遍历 k 个结点，之后同步遍历两个链表，这样就能够保证它们同时到达最后一个结点。",
      "由于两个链表从第一个公共结点到链表的尾结点都是重合的，所以它们肯定同时到达第 一个公共结点。",
      "l o a d b e i n g ^ str1 str2 i n g ^ 尾 部 对 齐 p q 算法的基本设计思想： ①分别求出 strl 和 str2 所指的两个链表的长度 m 和 n。",
