    "score": 2,
    "answer": "A",
    "question": "某进程访问页面的序列如下所示。 408真题系统 · ··, 1, 3, 4, 5, 6, 0, 3, 2, 3, 2, 0, 4, 0, 3, 2, 9, 2, 1, · ·· 时间 若工作集的窗口大小为 6，则在 t 时刻的工作集为（ ）。 A. {6, 0, 3, 2} B. {2, 3, 0, 4} C. {0, 4, 3, 2, 9} D. {4, 5, 6, 0, 3, 2}",
