    "answer": "（1）Web服务器IP=64.170.98.32；默认网关MAC=00-21-27-21-51-ee。（2）使用ARP解析下一跳网关MAC；ARP请求以太网帧目的MAC=FF-FF-FF-FF-FF-FF。（3）持续非流水线HTTP/1.1：HTML请求1个RTT，5个JPEG各1个RTT，共6个RTT。（4）经过NAT路由器：源IP由10.2.128.100改为101.12.123.15；TTL减1；IP首部校验和重算。若发生分片，分片相关字段也会改变。",
    "question": "某主机的 MAC 地址为 00-15-C5-C1-5E-28，IP 地址为 10.2.128.100（私有地址）。题 47-a 图是网络拓扑，题 47-b 图是该主机进行 Web 请求的 1 个以太网数据帧前 80 个字节的十六进制及 ASCII 码内容。 408真题系统 确认号 头部长度 服务类型 总长度 标识 标志 片偏移 生存时间（TTL） 协议 头部校验和 源 IP 地址 目的 IP 地址 47-d 图 IP 分组头结构 0 8 16 24 32 位 目的 MAC 地址 源 MAC 地址 类型 数 据 CRC 6B 6B 2B 46~1500B 4B 47-c 图 以太网帧结构 00 21 27 21 51 ee 00 15 c5 c1 5e 28 08 00 45 00 01 ef 11 3b 40 00 80 06 ba 9d 0a 02 80 64 40 aa 62 20 04 ff 00 50 e0 e2 00 fa 7b f9 f8 05 50 18 fa f0 1a c4 00 00 47 45 54 20 2f 72 66 63 2e 68 74 6d 6c 20 48 54 54 50 2f 31 2e 31 0d 0a 41 63 0000 0010 0020 0030 0040 .!!Q.. ..^(..E. ...:@... .....d@. b ...P.. ..{...P. ......GET /rfc.h tmI HTTP /1.1..Ac 47-b 图 以太网数据帧（前 80B） Internet 10.2.128.100 10.2.128.1 101.12.123.15 MTU = 1500B 47-a 图 网络拓扑 请参考图中的数据回答以下问题。 (1) Web 服务器的 IP 地址是什么？该主机的默认网关的 MAC 地址是什么？ (2) 该主机在构造题 47-b 图的数据帧时，使用什么协议确定目的 MAC 地址？封装该协议请求报文的以太网帧的目的 MAC 地址是什么？ (3) 假设 HTTP/1.1 协议以持续的非流水线方式工作，一次请求 - 响应时间为 RTT，rfc.html 页面引用了 5 个 JPEG 小图像，则从发出题 47-b 图中的 Web 请求开始到浏览器收到全部内容为止，需要多少个 RTT？ (4) 该帧所封装的 IP 分组经过路由器 R 转发时，需修改 IP 分组头中的哪些字段？ 注意：以太网数据帧结构和 IP 分组头结构分别如题 47-c 图、题 47-d 图所示。",
    "analysis": "1）以太网帧的数据部分是 IP 数据报，只要数出相应字段所在的字节即可。由图可知以太网帧头部有 6+6+2=14 字节，IP 数据报首部的目的 IP 地址字段前有 4×4=16 字节，从帧的第 1 字节开始数 14+16=30 字节，得目的 IP 地址 40.aa.62.20（十六进制），转换成十进制为 64.170.98.32。可知以太网帧的前 6 字节 00-21-27-21-51-ee 是的 MAC 地址，即为主机的默认网关 10.2.128.1 端口的 MAC 地址。 2）ARP 协议 于解决 IP 地址到 MAC 地址的映射问题。主机的 ARP 进程在本以太网以广播的形式发送 ARP 请求分组，在以太网上广播时，以太网帧的目的地址为全 1，即 FF-FF-FF-FF-FF-FF。 3）HTTP/1.1 协议以持续的 非流水线 方式工作时，服务器在发送响应后仍然在一段时间内保持这段连接，客户机在收到前一个请求的响应后才能发出下一个请求。第一个 RTT 用于请求 Web 页面，客户机收到第一个请求的响应后（还有五个请求未发送），每访问一次对象就用去一个 RTT。故共需 1+5=6 个 RTT 后浏览器收到全部内容。 4）源 IP 地址 0a.02.80.64 改为 65.0c.7b.0f；生存时间（TTL）减 1；校验和字段重新计算。私有地址和 Internet 的主机通信时，须由 NAT 路由器进行网络地址转换，把 IP 数据报的源 IP 地址（本题为私有地址 10.2.128.100）转换为 NAT 路由器的一个全球 IP 地址（本题为 101.12.123.15）因此，源 IP 地址字段 0a 02 80 64 变为 65 0c 7b 0f。IP 数据报每经过一个路由器，生存时间 TTL 值就减 1，并重新计算首部校验和。若 IP 分组的长度超过输出链路的 MTU，则总长度字段、标志字段、片偏移字段也要发生变化。 注意：题 47-b 图中每行前 4bit 是数据帧的字节计数，不属于以太网数据帧的内容。 【评分说明】若考生解答时将所有 IP 头中的字段进行罗列，不给分，其他情况的情给分。",
