    "typeName": "应用题",
    "score": 8,
    "answer": "(1) 柱面号15位、磁头/盘面号3位、扇区号9位。(2) 平均访问时间约9.18ms。(3) 每扇区产生64次DMA总线请求；CPU同时请求时DMA通常优先获得总线，以及时清空设备缓冲区。",
    "question": "假设某磁盘驱动器中有 4 个双面盘片，每个盘面有 20000 个磁道，每个磁道有 500 个扇区，每个扇区可记录 512 字节的数据，盘片转速为 7200rpm（转/分），平均寻道时间为 5ms，请回答下列问题。 (1) 每个扇区包含数据及地址信息，地址信息分为 3 个字段，这 3 个字段的名称格式什么？对于该磁盘，各字段至少占多少位？ (2) 一个扇区的平均访问时间约为多少？ (3) 若采用周期挪用 DMA 方式进行磁盘与主机之间的数据传送，磁盘控制器中的数据缓冲区大小为 64 位，则在一个扇区读写过程中，DMA 控制器向 CPU 发送了多少次总线请求？若 CPU 检测到 DMA 控制器的总线请求信号时也需要访问主存，则 DMA 控制器是否可以获得总线使用权？为什么？",
    "analysis": "8个记录面需要3位面号；20000个磁道需要15位柱面号；每磁道500个扇区需要9位扇区号。7200rpm对应一周8.333ms，平均旋转等待4.167ms；一个扇区传输时间约8.333/500=0.0167ms，加上5ms平均寻道时间，总计约9.183ms。64位缓冲区为8B，512B扇区需要512/8=64次DMA请求。周期挪用DMA需及时服务设备缓冲区，通常优先于CPU取得总线。",
